package com.networkers.groups;

import com.networkers.common.PageResponse;
import com.networkers.notification.NotificationService;
import com.networkers.security.CurrentUser;
import com.networkers.user.*;
import jakarta.persistence.EntityNotFoundException;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.boot.CommandLineRunner;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Transactional
public class GroupService implements CommandLineRunner {
 private final GroupRepository groups; private final GroupCategoryRepository categories; private final GroupMemberRepository members;
 private final GroupInvitationRepository invitations; private final GroupTopicRepository topics; private final GroupTopicCommentRepository comments;
 private final UserRepository users; private final NotificationService notifications;
 public GroupService(GroupRepository g,GroupCategoryRepository c,GroupMemberRepository m,GroupInvitationRepository i,GroupTopicRepository t,GroupTopicCommentRepository co,UserRepository u,NotificationService n){groups=g;categories=c;members=m;invitations=i;topics=t;comments=co;users=u;notifications=n;}
 private User actor(){return CurrentUser.get();}
 @Override public void run(String... args){for(String name:List.of("Real Estate","Technology","Healthcare","Finance","Marketing","Education","Construction","Legal Services","Business Networking","Other")){if(categories.findByNameIgnoreCaseAndActiveTrue(name).isEmpty()){GroupCategory c=new GroupCategory();c.setName(name);categories.save(c);}}}
 private Group group(Long id){return groups.findById(id).filter(Group::isActive).orElseThrow(()->new EntityNotFoundException("Group not found"));}
 private GroupTopic topic(Group g,Long id){return topics.findById(id).filter(t->t.isActive()&&t.getGroup().getId().equals(g.getId())).orElseThrow(()->new EntityNotFoundException("Topic not found"));}
 private void requireMember(Group g){if(!members.existsByGroupAndMember(g,actor()))throw new org.springframework.security.access.AccessDeniedException("Join the group to take this action");}
 public void requireGroupMember(Long id){requireMember(group(id));}
 private boolean ownerOrModerator(Group g){return members.findByGroupAndMember(g,actor()).map(m->m.getRole().equals("OWNER")||m.getRole().equals("MODERATOR")).orElse(false);}
 public List<GroupCategory> categories(){return categories.findByActiveTrueOrderByNameAsc();}
 public PageResponse<Map<String,Object>> discover(String q,Long cat,String sort,int page,int size){Pageable pageable=PageRequest.of(Math.max(0,page),Math.max(1,Math.min(50,size)),Sort.by(Sort.Direction.DESC,"createdAt"));Page<Group> result;
   if("active".equalsIgnoreCase(sort)) result=groups.recentlyActive(norm(q),cat,pageable);
   else if("popular".equalsIgnoreCase(sort))result=groups.popular(cat,norm(q),PageRequest.of(Math.max(0,page),Math.max(1,Math.min(50,size))));
   else result=groups.discover(norm(q),cat,pageable);
   return page(result.map(this::groupDto));}
 private Page<Group> pageSlice(List<Group> list,Pageable p){int from=(int)Math.min((long)p.getPageNumber()*p.getPageSize(),list.size());int to=Math.min(from+p.getPageSize(),list.size());return new PageImpl<>(list.subList(from,to),p,list.size());}
 public Map<String,Object> get(Long id){return groupDto(group(id));}
 public PageResponse<Map<String,Object>> suggested(int page,int size){return discover("",null,"popular",page,size);}
 public Map<String,Object> create(String name,String description,String category,String cover,List<Long> inviteIds){User me=actor();if(name==null||name.trim().length()<3||name.trim().length()>100)throw new IllegalArgumentException("Group name must be 3 to 100 characters");if(description==null||description.isBlank()||description.length()>3000)throw new IllegalArgumentException("Description is required and must be at most 3000 characters");GroupCategory cat=categories.findByNameIgnoreCaseAndActiveTrue(category==null?"":category.trim()).orElseGet(()->{if(category==null||category.isBlank()||category.length()>80)throw new IllegalArgumentException("Choose a valid category");GroupCategory created=new GroupCategory();created.setName(category.trim());return categories.save(created);});
   Group g=new Group();g.setName(name.trim());g.setDescription(description.trim());g.setCategory(cat);g.setCreator(me);g.setCoverImage(cover);g=groups.save(g);GroupMember membership=new GroupMember();membership.setGroup(g);membership.setMember(me);membership.setRole("OWNER");members.save(membership);sendInvitations(g,inviteIds,me);return groupDto(g);}
 public Map<String,Object> join(Long id){Group g=group(id);User me=actor();if(!members.existsByGroupAndMember(g,me)){GroupMember m=new GroupMember();m.setGroup(g);m.setMember(me);members.save(m);}return groupDto(g);}
 public void leave(Long id){Group g=group(id);GroupMember m=members.findByGroupAndMember(g,actor()).orElseThrow(()->new IllegalStateException("You are not a group member"));if(m.getRole().equals("OWNER"))throw new IllegalStateException("Owners cannot leave their group");members.delete(m);}
 public Map<String,Object> update(Long id,String name,String description,String category,String cover){Group g=group(id);if(!g.getCreator().getId().equals(actor().getId()))throw new org.springframework.security.access.AccessDeniedException("Only the group owner can edit group details");if(name==null||name.trim().length()<3||name.trim().length()>100||description==null||description.isBlank()||description.length()>3000)throw new IllegalArgumentException("Provide a valid group name and description");g.setName(name.trim());g.setDescription(description.trim());if(category!=null)g.setCategory(categories.findByNameIgnoreCaseAndActiveTrue(category.trim()).orElseThrow(()->new IllegalArgumentException("Choose a valid category")));g.setCoverImage(cover);return groupDto(g);}
 public void delete(Long id){Group g=group(id);if(!g.getCreator().getId().equals(actor().getId()))throw new org.springframework.security.access.AccessDeniedException("Only the owner can deactivate this group");g.setActive(false);}
 public Map<String,Object> members(Long id,int page,int size,String q){Group g=group(id);Pageable p=PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,100)),Sort.by("joinedAt").ascending());List<GroupMember> list=members.findByGroupOrderByJoinedAtAsc(g);String query=norm(q);List<Map<String,Object>> filtered=list.stream().filter(m->query.isEmpty()||m.getMember().getFullName().toLowerCase().contains(query)||Objects.toString(m.getMember().getBusinessCategory(),"").toLowerCase().contains(query)||Objects.toString(m.getMember().getLocation(),"").toLowerCase().contains(query)||m.getMember().getChapter()!=null&&m.getMember().getChapter().getChapterName().toLowerCase().contains(query)).map(this::memberDto).toList();return Map.of("content",filtered.stream().skip((long)p.getPageNumber()*p.getPageSize()).limit(p.getPageSize()).toList(),"page",p.getPageNumber(),"size",p.getPageSize(),"totalElements",filtered.size(),"totalPages",(filtered.size()+p.getPageSize()-1)/p.getPageSize());}
 public PageResponse<Map<String,Object>> myGroups(String type,int page,int size){User me=actor();List<Group> list=members.findByMemberOrderByJoinedAtDesc(me).stream().map(GroupMember::getGroup).filter(Group::isActive).filter(g->"created".equalsIgnoreCase(type)?g.getCreator().getId().equals(me.getId()):!"joined".equalsIgnoreCase(type)||!g.getCreator().getId().equals(me.getId())).toList();Pageable p=PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,50)));List<Map<String,Object>> rows=list.stream().map(this::groupDto).toList();int from=(int)Math.min((long)p.getPageNumber()*p.getPageSize(),rows.size()),to=Math.min(from+p.getPageSize(),rows.size());return new PageResponse<>(rows.subList(from,to),p.getPageNumber(),p.getPageSize(),rows.size(),(rows.size()+p.getPageSize()-1)/p.getPageSize());}
 public PageResponse<Map<String,Object>> invitations(String status,boolean received,int page,int size){Pageable p=PageRequest.of(Math.max(0,page),Math.max(1,Math.min(50,size)),Sort.by(Sort.Direction.DESC,"createdAt"));Page<GroupInvitation> result=received?invitations.findByInvitedMemberAndStatusOrderByCreatedAtDesc(actor(),status==null?"SENT":status.toUpperCase(),p):invitations.findByInvitedByOrderByCreatedAtDesc(actor(),p);return page(result.map(this::invitationDto));}
 public List<Map<String,Object>> invite(Long id,List<Long> ids){Group g=group(id);User from=actor();if(!g.getCreator().getId().equals(from.getId())&&!ownerOrModerator(g))throw new org.springframework.security.access.AccessDeniedException("Only group owners and moderators can invite members");return sendInvitations(g,ids,from);}
 private List<Map<String,Object>> sendInvitations(Group g,List<Long> ids,User from){if(!members.existsByGroupAndMember(g,from))throw new org.springframework.security.access.AccessDeniedException("Join the group before inviting members");if(ids==null||ids.isEmpty())throw new IllegalArgumentException("Select at least one member");List<Map<String,Object>> result=new ArrayList<>();for(Long id:new LinkedHashSet<>(ids)){if(id==null||id.equals(from.getId()))throw new IllegalArgumentException("You cannot invite yourself");User to=users.findById(id).filter(u->!u.isDeleted()&&u.isEnabled()).orElseThrow(()->new EntityNotFoundException("Member not found"));if(members.existsByGroupAndMember(g,to)||invitations.existsByGroupAndInvitedMemberAndStatus(g,to,"SENT"))continue;GroupInvitation invitation=new GroupInvitation();invitation.setGroup(g);invitation.setInvitedBy(from);invitation.setInvitedMember(to);invitation=invitations.save(invitation);notifications.notify(to,"Group invitation",from.getFullName()+" invited you to join “"+g.getName()+"”. It is an open group you can join anytime.");result.add(invitationDto(invitation));}return result;}
 public Map<String,Object> respond(Long id,boolean accept){GroupInvitation i=invitations.findById(id).orElseThrow(()->new EntityNotFoundException("Invitation not found"));if(!i.getInvitedMember().getId().equals(actor().getId()))throw new org.springframework.security.access.AccessDeniedException("This invitation belongs to another member");if(!i.getStatus().equals("SENT"))throw new IllegalStateException("This invitation is no longer active");i.setStatus(accept?"ACCEPTED":"DECLINED");i.setRespondedAt(LocalDateTime.now());if(accept)join(i.getGroup().getId());return invitationDto(i);}
 public void cancelInvitation(Long id){GroupInvitation i=invitations.findById(id).orElseThrow(()->new EntityNotFoundException("Invitation not found"));if(!i.getInvitedBy().getId().equals(actor().getId())&&!ownerOrModerator(i.getGroup()))throw new org.springframework.security.access.AccessDeniedException("Only the inviter or group moderators can cancel this invitation");if(!i.getStatus().equals("SENT"))throw new IllegalStateException("Only pending invitations can be cancelled");i.setStatus("CANCELLED");i.setRespondedAt(LocalDateTime.now());}
 public Map<String,Object> createTopic(Long id,String title,String description,String attachment){Group g=group(id);requireMember(g);if(title==null||title.isBlank()||title.length()>160||description==null||description.isBlank()||description.length()>10000)throw new IllegalArgumentException("Provide a topic title and discussion content");GroupTopic t=new GroupTopic();t.setGroup(g);t.setCreator(actor());t.setTitle(title.trim());t.setDescription(description.trim());t.setAttachmentUrl(attachment);return topicDto(topics.save(t));}
 public PageResponse<Map<String,Object>> topicFeed(Long id,boolean history,int page,int size){Group g=group(id);requireMember(g);Pageable p=PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,50)));Page<GroupTopic> result=topics.feed(g,LocalDateTime.now().minusDays(30),history,p);return page(result.map(this::topicDto));}
 public Map<String,Object> topicDetails(Long gid,Long tid,int page,int size){Group g=group(gid);requireMember(g);GroupTopic t=topic(g,tid);Pageable p=PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,100)),Sort.by(Sort.Direction.ASC,"createdAt"));Map<String,Object> out=new LinkedHashMap<>(topicDto(t));out.put("comments",page(comments.findByTopicAndActiveTrueOrderByCreatedAtAsc(t,p).map(this::commentDto)));return out;}
 public Map<String,Object> updateTopic(Long gid,Long tid,String title,String description,String attachment){Group g=group(gid);GroupTopic t=topic(g,tid);if(!t.getCreator().getId().equals(actor().getId())&&!ownerOrModerator(g))throw new org.springframework.security.access.AccessDeniedException("Only the topic creator or a moderator can edit this topic");if(title==null||title.isBlank()||title.length()>160||description==null||description.isBlank()||description.length()>10000)throw new IllegalArgumentException("Provide a valid title and discussion content");t.setTitle(title.trim());t.setDescription(description.trim());t.setAttachmentUrl(attachment);return topicDto(t);}
 public void deleteTopic(Long gid,Long tid){Group g=group(gid);GroupTopic t=topic(g,tid);if(!t.getCreator().getId().equals(actor().getId())&&!ownerOrModerator(g))throw new org.springframework.security.access.AccessDeniedException("Only the topic creator or a moderator can delete this topic");t.setActive(false);}
 public Map<String,Object> addComment(Long gid,Long tid,String text){Group g=group(gid);requireMember(g);GroupTopic t=topic(g,tid);if(text==null||text.isBlank()||text.length()>2000)throw new IllegalArgumentException("Comment must be between 1 and 2000 characters");GroupTopicComment c=new GroupTopicComment();c.setGroup(g);c.setTopic(t);c.setMember(actor());c.setComment(text.trim());if(!t.getCreator().getId().equals(actor().getId()))notifications.notify(t.getCreator(),"New group discussion comment",actor().getFullName()+" commented on “"+t.getTitle()+"”.");return commentDto(comments.save(c));}
 public Map<String,Object> editComment(Long gid,Long tid,Long cid,String text){Group g=group(gid);GroupTopic t=topic(g,tid);GroupTopicComment c=comments.findById(cid).filter(x->x.isActive()&&x.getTopic().getId().equals(t.getId())).orElseThrow(()->new EntityNotFoundException("Comment not found"));if(!c.getMember().getId().equals(actor().getId())&&!ownerOrModerator(g))throw new org.springframework.security.access.AccessDeniedException("Only the commenter or a moderator can edit this comment");if(text==null||text.isBlank()||text.length()>2000)throw new IllegalArgumentException("Comment must be between 1 and 2000 characters");c.setComment(text.trim());return commentDto(c);}
 public void deleteComment(Long gid,Long tid,Long cid){Group g=group(gid);GroupTopic t=topic(g,tid);GroupTopicComment c=comments.findById(cid).filter(x->x.isActive()&&x.getTopic().getId().equals(t.getId())).orElseThrow(()->new EntityNotFoundException("Comment not found"));if(!c.getMember().getId().equals(actor().getId())&&!ownerOrModerator(g))throw new org.springframework.security.access.AccessDeniedException("Only the commenter or a moderator can delete this comment");c.setActive(false);}
 private Map<String,Object> groupDto(Group g){Map<String,Object> m=new LinkedHashMap<>();m.put("id",g.getId());m.put("name",g.getName());m.put("description",g.getDescription());m.put("category",g.getCategory().getName());m.put("categoryId",g.getCategory().getId());m.put("creator",userDto(g.getCreator()));m.put("coverImage",g.getCoverImage());m.put("accessType","OPEN");m.put("createdAt",g.getCreatedAt());m.put("updatedAt",g.getUpdatedAt());m.put("memberCount",members.countByGroup(g));m.put("topicCount",topics.countByGroupAndActiveTrue(g));m.put("joined",members.existsByGroupAndMember(g,actor()));m.put("owner",g.getCreator().getId().equals(actor().getId()));return m;}
 private Map<String,Object> topicDto(GroupTopic t){Map<String,Object> m=new LinkedHashMap<>();m.put("id",t.getId());m.put("title",t.getTitle());m.put("description",t.getDescription());m.put("attachmentUrl",t.getAttachmentUrl());m.put("creator",userDto(t.getCreator()));m.put("createdAt",t.getCreatedAt());m.put("updatedAt",t.getUpdatedAt());m.put("commentCount",comments.countByTopicAndActiveTrue(t));return m;}
 private Map<String,Object> commentDto(GroupTopicComment c){return Map.of("id",c.getId(),"comment",c.getComment(),"member",userDto(c.getMember()),"createdAt",c.getCreatedAt(),"updatedAt",c.getUpdatedAt());}
 private Map<String,Object> memberDto(GroupMember m){Map<String,Object> d=new LinkedHashMap<>(userDto(m.getMember()));d.put("role",m.getRole());d.put("joinedAt",m.getJoinedAt());return d;}
 private Map<String,Object> invitationDto(GroupInvitation i){return Map.of("id",i.getId(),"group",Map.of("id",i.getGroup().getId(),"name",i.getGroup().getName(),"category",i.getGroup().getCategory().getName()),"invitedBy",userDto(i.getInvitedBy()),"invitedMember",userDto(i.getInvitedMember()),"status",i.getStatus(),"createdAt",i.getCreatedAt(),"respondedAt",i.getRespondedAt()==null?"":i.getRespondedAt());}
 private Map<String,Object> userDto(User u){Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.getId());m.put("fullName",u.getFullName());m.put("profileImage",u.getProfileImage());m.put("businessName",u.getBusinessName());m.put("businessCategory",u.getBusinessCategory());m.put("location",u.getLocation());m.put("chapterName",u.getChapter()==null?"":u.getChapter().getChapterName());return m;}
 private <T> PageResponse<T> page(Page<T> p){return new PageResponse<>(p.getContent(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
 private String norm(String s){return s==null?"":s.trim().toLowerCase();}
}
